CREATE TABLE "c_BillingAccount" ("id" BIGINT NOT NULL, "a_BillingAccount_balance" NUMERIC NOT NULL, "r_PatientBilling_source_id" BIGINT, "r_PatientBilling_source_dtype" TEXT, PRIMARY KEY ("id"), UNIQUE ("r_PatientBilling_source_id"), CHECK ("r_PatientBilling_source_dtype" IS NULL OR "r_PatientBilling_source_dtype" IN ('Patient')), CHECK ((TRUE) OR "r_PatientBilling_source_id" IS NULL), CHECK (NOT (TRUE) OR "r_PatientBilling_source_id" IS NOT NULL));
CREATE TABLE "c_Department" ("id" BIGINT NOT NULL, "a_Department_name" TEXT NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "c_Encounter" ("id" BIGINT NOT NULL, "a_Encounter_admit_time" TIMESTAMP NOT NULL, "a_Encounter_discharge_time" TIMESTAMP, PRIMARY KEY ("id"));
CREATE TABLE "c_InsurancePlan" ("id" BIGINT NOT NULL, "a_InsurancePlan_payer" TEXT NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "c_OrderRequest" ("id" BIGINT NOT NULL, "dtype" TEXT NOT NULL, "a_LabOrder_specimen" TEXT, "a_MedicationOrder_route" TEXT, "a_OrderRequest_priority" TEXT, "r_EncounterOrders_source_id" BIGINT, PRIMARY KEY ("id"), UNIQUE ("id", "dtype"), CHECK (dtype IN ('LabOrder','MedicationOrder','OrderRequest')), CHECK ((dtype IN ('LabOrder')) OR "a_LabOrder_specimen" IS NULL), CHECK (NOT (dtype IN ('LabOrder')) OR "a_LabOrder_specimen" IS NOT NULL), CHECK ((dtype IN ('MedicationOrder')) OR "a_MedicationOrder_route" IS NULL), CHECK (NOT (dtype IN ('MedicationOrder')) OR "a_MedicationOrder_route" IS NOT NULL), CHECK ((dtype IN ('LabOrder','MedicationOrder','OrderRequest')) OR "a_OrderRequest_priority" IS NULL), CHECK (NOT (dtype IN ('LabOrder','MedicationOrder','OrderRequest')) OR "a_OrderRequest_priority" IS NOT NULL), CHECK ((dtype IN ('LabOrder','MedicationOrder','OrderRequest')) OR "r_EncounterOrders_source_id" IS NULL), CHECK (NOT (dtype IN ('LabOrder','MedicationOrder','OrderRequest')) OR "r_EncounterOrders_source_id" IS NOT NULL));
CREATE TABLE "c_Person" ("id" BIGINT NOT NULL, "dtype" TEXT NOT NULL, "a_Patient_mrn" TEXT, "a_Person_name" TEXT, "a_Person_dob" DATE, "a_Provider_credential" TEXT, PRIMARY KEY ("id"), UNIQUE ("id", "dtype"), CHECK (dtype IN ('Patient','Person','Provider')), CHECK ((dtype IN ('Patient')) OR "a_Patient_mrn" IS NULL), CHECK (NOT (dtype IN ('Patient')) OR "a_Patient_mrn" IS NOT NULL), CHECK ((dtype IN ('Patient','Person','Provider')) OR "a_Person_name" IS NULL), CHECK (NOT (dtype IN ('Patient','Person','Provider')) OR "a_Person_name" IS NOT NULL), CHECK ((dtype IN ('Patient','Person','Provider')) OR "a_Person_dob" IS NULL), CHECK (NOT (dtype IN ('Patient','Person','Provider')) OR "a_Person_dob" IS NOT NULL), CHECK ((dtype IN ('Provider')) OR "a_Provider_credential" IS NULL), CHECK (NOT (dtype IN ('Provider')) OR "a_Provider_credential" IS NOT NULL));
CREATE TABLE "c_Result" ("id" BIGINT NOT NULL, "a_Result_value_text" TEXT NOT NULL, "r_OrderResults_source_id" BIGINT, "r_OrderResults_source_dtype" TEXT, PRIMARY KEY ("id"), CHECK ("r_OrderResults_source_dtype" IS NULL OR "r_OrderResults_source_dtype" IN ('LabOrder','MedicationOrder','OrderRequest')), CHECK ((TRUE) OR "r_OrderResults_source_id" IS NULL), CHECK (NOT (TRUE) OR "r_OrderResults_source_id" IS NOT NULL));
CREATE TABLE "l_DepartmentProviders" ("r_DepartmentProviders_source_id" BIGINT NOT NULL, "r_DepartmentProviders_target_id" BIGINT NOT NULL, "r_DepartmentProviders_target_dtype" TEXT NOT NULL, PRIMARY KEY ("r_DepartmentProviders_source_id", "r_DepartmentProviders_target_id"), UNIQUE ("r_DepartmentProviders_target_id"), CHECK ("r_DepartmentProviders_target_dtype" IS NULL OR "r_DepartmentProviders_target_dtype" IN ('Provider')));
CREATE TABLE "l_PatientEncounters" ("r_PatientEncounters_source_id" BIGINT NOT NULL, "r_PatientEncounters_source_dtype" TEXT NOT NULL, "r_PatientEncounters_target_id" BIGINT NOT NULL, PRIMARY KEY ("r_PatientEncounters_source_id", "r_PatientEncounters_target_id"), UNIQUE ("r_PatientEncounters_target_id"), CHECK ("r_PatientEncounters_source_dtype" IS NULL OR "r_PatientEncounters_source_dtype" IN ('Patient')));
CREATE TABLE "l_PatientPlans" ("r_PatientPlans_source_id" BIGINT NOT NULL, "r_PatientPlans_source_dtype" TEXT NOT NULL, "r_PatientPlans_target_id" BIGINT NOT NULL, PRIMARY KEY ("r_PatientPlans_source_id", "r_PatientPlans_target_id"), CHECK ("r_PatientPlans_source_dtype" IS NULL OR "r_PatientPlans_source_dtype" IN ('Patient')));
CREATE TABLE "l_ProviderEncounters" ("r_ProviderEncounters_source_id" BIGINT NOT NULL, "r_ProviderEncounters_source_dtype" TEXT NOT NULL, "r_ProviderEncounters_target_id" BIGINT NOT NULL, PRIMARY KEY ("r_ProviderEncounters_source_id", "r_ProviderEncounters_target_id"), CHECK ("r_ProviderEncounters_source_dtype" IS NULL OR "r_ProviderEncounters_source_dtype" IN ('Provider')));
ALTER TABLE "c_BillingAccount" ADD CONSTRAINT "fk_c_BillingAccount_0" FOREIGN KEY ("r_PatientBilling_source_id", "r_PatientBilling_source_dtype") REFERENCES "c_Person" ("id", "dtype") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "c_OrderRequest" ADD CONSTRAINT "fk_c_OrderRequest_0" FOREIGN KEY ("r_EncounterOrders_source_id") REFERENCES "c_Encounter" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "c_Result" ADD CONSTRAINT "fk_c_Result_0" FOREIGN KEY ("r_OrderResults_source_id", "r_OrderResults_source_dtype") REFERENCES "c_OrderRequest" ("id", "dtype") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_DepartmentProviders" ADD CONSTRAINT "fk_l_DepartmentProviders_0" FOREIGN KEY ("r_DepartmentProviders_source_id") REFERENCES "c_Department" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_DepartmentProviders" ADD CONSTRAINT "fk_l_DepartmentProviders_1" FOREIGN KEY ("r_DepartmentProviders_target_id", "r_DepartmentProviders_target_dtype") REFERENCES "c_Person" ("id", "dtype") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_PatientEncounters" ADD CONSTRAINT "fk_l_PatientEncounters_0" FOREIGN KEY ("r_PatientEncounters_source_id", "r_PatientEncounters_source_dtype") REFERENCES "c_Person" ("id", "dtype") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_PatientEncounters" ADD CONSTRAINT "fk_l_PatientEncounters_1" FOREIGN KEY ("r_PatientEncounters_target_id") REFERENCES "c_Encounter" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_PatientPlans" ADD CONSTRAINT "fk_l_PatientPlans_0" FOREIGN KEY ("r_PatientPlans_source_id", "r_PatientPlans_source_dtype") REFERENCES "c_Person" ("id", "dtype") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_PatientPlans" ADD CONSTRAINT "fk_l_PatientPlans_1" FOREIGN KEY ("r_PatientPlans_target_id") REFERENCES "c_InsurancePlan" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_ProviderEncounters" ADD CONSTRAINT "fk_l_ProviderEncounters_0" FOREIGN KEY ("r_ProviderEncounters_source_id", "r_ProviderEncounters_source_dtype") REFERENCES "c_Person" ("id", "dtype") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_ProviderEncounters" ADD CONSTRAINT "fk_l_ProviderEncounters_1" FOREIGN KEY ("r_ProviderEncounters_target_id") REFERENCES "c_Encounter" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
CREATE FUNCTION "require_DepartmentProviders"() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $ymap$ BEGIN IF EXISTS (SELECT 1 FROM "c_Person" t WHERE (t.dtype IN ('Provider')) AND NOT EXISTS (SELECT 1 FROM "l_DepartmentProviders" l WHERE l."r_DepartmentProviders_target_id"=t.id)) THEN RAISE EXCEPTION 'Required target participation violated: DepartmentProviders'; END IF; RETURN NULL; END; $ymap$;
CREATE CONSTRAINT TRIGGER "ct_DepartmentProviders_target" AFTER INSERT OR UPDATE OR DELETE ON "c_Person" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_DepartmentProviders"();
CREATE CONSTRAINT TRIGGER "ct_DepartmentProviders_link" AFTER INSERT OR UPDATE OR DELETE ON "l_DepartmentProviders" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_DepartmentProviders"();
CREATE FUNCTION "require_PatientEncounters"() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $ymap$ BEGIN IF EXISTS (SELECT 1 FROM "c_Encounter" t WHERE (TRUE) AND NOT EXISTS (SELECT 1 FROM "l_PatientEncounters" l WHERE l."r_PatientEncounters_target_id"=t.id)) THEN RAISE EXCEPTION 'Required target participation violated: PatientEncounters'; END IF; RETURN NULL; END; $ymap$;
CREATE CONSTRAINT TRIGGER "ct_PatientEncounters_target" AFTER INSERT OR UPDATE OR DELETE ON "c_Encounter" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_PatientEncounters"();
CREATE CONSTRAINT TRIGGER "ct_PatientEncounters_link" AFTER INSERT OR UPDATE OR DELETE ON "l_PatientEncounters" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_PatientEncounters"();